export const EDITOR_HTML: string = "<!doctype html>\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>ios-cal-sub · 在线编辑器</title>\r\n<style>\r\n  :root {\r\n    color-scheme: light dark;\r\n    --bg:#f5f5f7; --card:#fff; --text:#1d1d1f; --muted:#6e6e73;\r\n    --line:#d2d2d7; --accent:#0a84ff; --danger:#ff3b30; --ok:#34c759;\r\n  }\r\n  @media (prefers-color-scheme: dark) {\r\n    :root { --bg:#1c1c1e; --card:#2c2c2e; --text:#f2f2f7; --muted:#98989d; --line:#48484a; }\r\n  }\r\n  * { box-sizing:border-box; }\r\n  body { margin:0; background:var(--bg); color:var(--text);\r\n         font-family:-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif; }\r\n  header { position:sticky; top:0; z-index:10; background:var(--bg); border-bottom:1px solid var(--line);\r\n           padding:12px 18px; display:flex; align-items:center; gap:10px; flex-wrap:wrap; }\r\n  header h1 { font-size:17px; margin:0; flex:1; min-width:220px; }\r\n  main { max-width:880px; margin:0 auto; padding:16px 14px 90px; }\r\n  .btn { padding:8px 15px; border-radius:9px; border:none; background:var(--accent); color:#fff;\r\n         cursor:pointer; font-size:14px; text-decoration:none; display:inline-block; }\r\n  .btn.secondary { background:transparent; color:var(--accent); border:1px solid var(--accent); }\r\n  .btn.ghost { background:transparent; color:var(--muted); border:1px solid var(--line); }\r\n  .btn.danger { background:transparent; color:var(--danger); border:1px solid var(--danger); }\r\n  .btn.small { padding:4px 10px; font-size:13px; }\r\n  .btn:disabled { opacity:.5; cursor:not-allowed; }\r\n  .seg { display:inline-flex; border:1px solid var(--line); border-radius:999px; overflow:hidden; }\r\n  .segbtn { padding:6px 16px; font-size:13px; background:transparent; color:var(--muted);\r\n            border:0; cursor:pointer; user-select:none; }\r\n  .segbtn.on { background:var(--accent); color:#fff; }\r\n  .tabs { display:flex; gap:8px; flex-wrap:wrap; margin:4px 0 16px; }\r\n  .tab { padding:7px 14px; border-radius:999px; border:1px solid var(--line);\r\n         background:var(--card); cursor:pointer; font-size:14px; user-select:none; }\r\n  .tab.active { background:var(--accent); color:#fff; border-color:var(--accent); }\r\n  .cardbox { background:var(--card); border:1px solid var(--line); border-radius:14px;\r\n             padding:14px 16px; margin-bottom:14px; }\r\n  .ev { display:flex; align-items:center; gap:12px; padding:11px 2px; border-bottom:1px solid var(--line); }\r\n  .ev:last-child { border-bottom:none; }\r\n  .ev .ico { font-size:21px; width:26px; text-align:center; }\r\n  .ev .info { flex:1; min-width:0; }\r\n  .ev .t { font-size:15px; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\r\n  .ev .s { font-size:12.5px; color:var(--muted); margin-top:2px; word-break:break-all; }\r\n  .ev .ops { display:flex; gap:6px; flex-shrink:0; flex-wrap:wrap; justify-content:flex-end; }\r\n  h2.sect { font-size:14px; color:var(--muted); margin:20px 0 10px; font-weight:600; }\r\n  .grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(200px,1fr)); gap:12px; }\r\n  label.f { display:flex; flex-direction:column; gap:5px; font-size:13px; color:var(--muted); }\r\n  label.f > span b { color:var(--text); font-weight:500; }\r\n  input, select { font:inherit; padding:8px 10px; border-radius:9px; border:1px solid var(--line);\r\n                  background:var(--bg); color:var(--text); width:100%; }\r\n  input:focus, select:focus { outline:2px solid #0a84ff55; border-color:var(--accent); }\r\n  .chips { display:flex; gap:6px; flex-wrap:wrap; }\r\n  .chip { padding:5px 11px; border-radius:999px; border:1px solid var(--line);\r\n          cursor:pointer; font-size:13px; user-select:none; display:inline-block; }\r\n  .chip.on { background:var(--accent); color:#fff; border-color:var(--accent); }\r\n  dialog { border:none; border-radius:16px; background:var(--card); color:var(--text);\r\n           max-width:660px; width:calc(100vw - 32px); padding:0; }\r\n  dialog::backdrop { background:rgba(0,0,0,.45); }\r\n  .dlg-h { display:flex; align-items:center; justify-content:space-between; padding:15px 18px;\r\n           border-bottom:1px solid var(--line); }\r\n  .dlg-h h3 { margin:0; font-size:16px; }\r\n  .dlg-b { padding:16px 18px; max-height:64vh; overflow:auto; }\r\n  .dlg-f { padding:12px 18px; border-top:1px solid var(--line); display:flex; gap:10px; justify-content:flex-end; }\r\n  .typegrid { display:grid; grid-template-columns:repeat(auto-fill,minmax(110px,1fr)); gap:8px; margin-bottom:16px; }\r\n  .typeopt { padding:11px 8px; border-radius:12px; border:2px solid var(--line); text-align:center;\r\n             cursor:pointer; font-size:12.5px; }\r\n  .typeopt .i { font-size:22px; display:block; margin-bottom:4px; }\r\n  .typeopt.on { border-color:var(--accent); background:color-mix(in srgb,var(--accent) 12%,transparent); }\r\n  #lock { position:fixed; inset:0; z-index:50; background:var(--bg); display:flex;\r\n          align-items:center; justify-content:center; }\r\n  #lock .box { width:min(400px,92vw); text-align:center; }\r\n  #lock input { text-align:center; letter-spacing:.06em; font-size:16px; margin:14px 0; }\r\n  #log { white-space:pre-wrap; font:12px/1.6 ui-monospace,Consolas,monospace; background:var(--card);\r\n         border:1px solid var(--line); border-radius:12px; padding:10px 14px; margin-top:12px;\r\n         max-height:180px; overflow:auto; display:none; }\r\n  .hint { font-size:12.5px; color:var(--muted); line-height:1.7; }\r\n  .row { display:flex; gap:10px; align-items:end; flex-wrap:wrap; }\r\n  #toast { position:fixed; left:50%; bottom:24px; transform:translateX(-50%); background:var(--text);\r\n           color:var(--bg); padding:10px 20px; border-radius:999px; font-size:14px; opacity:0;\r\n           transition:opacity .25s; pointer-events:none; max-width:92vw; z-index:99; }\r\n  #toast.show { opacity:1; } #toast.err { background:var(--danger); color:#fff; }\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<div id=\"lock\" style=\"display:none\">\r\n  <div class=\"box cardbox\">\r\n    <div style=\"font-size:34px\">🔐</div>\r\n    <h2 style=\"margin:8px 0\">编辑器已锁定</h2>\r\n    <p class=\"hint\">输入访问密钥(UUID)解锁。密钥由站长通过 <code>pnpm cal:key</code> 生成。</p>\r\n    <input id=\"lockKey\" placeholder=\"xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx\">\r\n    <button class=\"btn\" style=\"width:100%\" onclick=\"tryUnlock()\">🔓 解锁</button>\r\n    <p class=\"hint\" id=\"lockHint\" style=\"margin-top:10px\"></p>\r\n  </div>\r\n</div>\r\n\r\n<header>\r\n  <h1>📅 在线编辑器 <span class=\"hint\" id=\"meta\"></span></h1>\r\n  <a class=\"btn ghost small\" href=\"../index.html\">👁 订阅页</a>\r\n  <button class=\"btn ghost small\" onclick=\"openKeySettings()\">🔑 访问密钥</button>\r\n  <button class=\"btn ghost small\" onclick=\"openSettings()\">⚙ 全局设置</button>\r\n  <button class=\"btn\" id=\"saveBtn\" onclick=\"saveToWorker()\">💾 保存到云端</button>\r\n</header>\r\n<main>\r\n  <div class=\"tabs\" id=\"tabs\"></div>\r\n  <div id=\"calPanel\"></div>\r\n  <div id=\"log\"></div>\r\n  <p class=\"hint\" style=\"margin-top:14px\" id=\"footNote\"></p>\r\n</main>\r\n\r\n<dialog id=\"dlg\"><div class=\"dlg-h\"><h3 id=\"dlgTitle\">编辑事件</h3>\r\n  <button class=\"btn ghost small\" onclick=\"closeDlg()\">✕</button></div>\r\n  <div class=\"dlg-b\" id=\"dlgBody\"></div>\r\n  <div class=\"dlg-f\">\r\n    <button class=\"btn ghost\" onclick=\"closeDlg()\">取消</button>\r\n    <button class=\"btn\" id=\"dlgOk\" onclick=\"submitDlg()\">确定</button>\r\n  </div>\r\n</dialog>\r\n<div id=\"toast\"></div>\r\n\r\n<!-- 构建期生成:与 Node 端完全一致的 YAML 序列化器(全局 const dumpYaml) -->\r\n<script src=\"/editor/yaml-dump.js\"></script>\r\n<script src=\"/qrcode.min.js\"></script>\r\n<script>\r\n'use strict';\r\nconst TYPES = {\r\n  'lunar':          { icon:'🌙', label:'农历生日 / 纪念日' },\r\n  'solar':          { icon:'📌', label:'固定公历日期' },\r\n  'rule':           { icon:'⏰', label:'周期规则' },\r\n  'solar-term':     { icon:'⛅', label:'节气事件' },\r\n  'lunar-festival': { icon:'🏮', label:'农历传统节日' },\r\n  'holidays-cn':    { icon:'🇨🇳', label:'节假日数据源' },\r\n  'solar-terms':    { icon:'⛅', label:'二十四节气(全部)' },\r\n};\r\nconst TERMS = ['立春','雨水','惊蛰','春分','清明','谷雨','立夏','小满','芒种','夏至','小暑','大暑',\r\n               '立秋','处暑','白露','秋分','寒露','霜降','立冬','小雪','大雪','冬至','小寒','大寒'];\r\nconst LUNAR_FESTIVALS = ['春节','元宵节','龙抬头','清明节','上巳节','端午节','七夕节','中元节',\r\n                         '中秋节','重阳节','寒衣节','下元节','腊八节','冬至',\r\n                         '小年(北方)','小年(南方)','除夕'];\r\nconst WEEKDAYS = [['mon','周一'],['tue','周二'],['wed','周三'],['thu','周四'],['fri','周五'],['sat','周六'],['sun','周日']];\r\nconst ALARM_DAYS = [0,1,2,3,7,14];\r\nconst CN_MONTH = ['正','二','三','四','五','六','七','八','九','十','冬','腊'];\r\n\r\nlet cfg = null, metaTime = '';\r\nlet active = 0, editState = null, editSnapshot = null;\r\nlet auth = { enabled:false, sha256:'', hint:'' };\r\n\r\nconst $ = (id)=>document.getElementById(id);\r\nconst esc = (s)=>String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\r\nfunction toast(msg, isErr){ const t=$('toast'); t.textContent=msg; t.className='show'+(isErr?' err':'');\r\n  setTimeout(()=>{t.className='';}, isErr?5200:2800); }\r\n\r\nasync function sha256Hex(str){\r\n  const buf = new TextEncoder().encode(str.trim().toLowerCase()); // 大小写归一,与 keygen 保持一致\r\n  const dig = await crypto.subtle.digest('SHA-256', buf);\r\n  return [...new Uint8Array(dig)].map(b=>b.toString(16).padStart(2,'0')).join('');\r\n}\r\n\r\n/* ---------- 门禁 ---------- */\r\nasync function gate(){\r\n  auth = await (await fetch('/editor/auth.json',{cache:'no-store'})).json();\r\n  if (!auth.enabled) { $('footNote').textContent =\r\n    '⚠️ 当前未启用访问密钥(未设置 EDITOR_KEY_SHA256)。任何人都能打开本页;保存配置仍需要密钥。'; return; }\r\n  if (sessionStorage.getItem('ics_unlocked') === auth.sha256) return;\r\n  $('lock').style.display='flex';\r\n  $('lockHint').textContent = auth.hint ? ('提示:'+auth.hint) : '';\r\n  $('lockKey').focus();\r\n  return new Promise((resolve)=>{\r\n    $('lockKey').onkeydown = (e)=>{ if(e.key==='Enter') tryUnlock().then(resolve); };\r\n    window._unlockResolve = resolve;\r\n  });\r\n}\r\nasync function tryUnlock(){\r\n  const v = $('lockKey').value;\r\n  const h = await sha256Hex(v);\r\n  if (h === auth.sha256) {\r\n    sessionStorage.setItem('ics_unlocked', h);\r\n    sessionStorage.setItem('ics_edit_key', v.trim().toLowerCase()); // 私密订阅链接的派生材料,仅存本机\r\n    $('lock').style.display='none';\r\n    toast('✅ 已解锁');\r\n    if (window._unlockResolve){ window._unlockResolve(); window._unlockResolve=null; }\r\n  } else { toast('密钥不对,再试试', true); }\r\n}\r\n/* 私密订阅令牌(与构建端一致):sha256( sha256(UUID)hex + '|' + calId ) 前32位 */\r\nasync function subTokenFor(calId){  const k=sessionStorage.getItem('ics_edit_key');\r\n  if(!k) return null;\r\n  const h1=await sha256Hex(k);\r\n  const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(h1+'|'+calId));\r\n  return [...new Uint8Array(d)].map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,32);\r\n}\r\nfunction siteBase(){\r\n  if(cfg?.site_base_url) return cfg.site_base_url.replace(/\\/+$/,'');\r\n  return location.href.split('/editor')[0]; // 部署后从地址推断\r\n}\r\n/* ---------- 二维码(iPhone 相机扫码即订阅) ---------- */\r\nfunction webcalOf(u){ return u.replace(/^https?:\\/\\//,'webcal://'); }\r\nfunction renderQrInto(el,text){\r\n  if(!el || typeof qrcode==='undefined'){ if(el)el.innerHTML='<span class=\"hint\">二维码组件未加载</span>'; return; }\r\n  const qr=qrcode(0,'M'); qr.addData(text,'Byte'); qr.make();\r\n  const n=qr.getModuleCount();\r\n  let s='<svg viewBox=\"0 0 '+n+' '+n+'\" style=\"width:152px;height:152px\" shape-rendering=\"crispEdges\">';\r\n  for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(qr.isDark(r,c))s+='<rect x=\"'+c+'\" y=\"'+r+'\" width=\"1\" height=\"1\"/>';\r\n  s+='</svg>';\r\n  el.innerHTML='<div style=\"display:inline-block;background:#fff;padding:8px;border-radius:10px;box-shadow:0 1px 6px #0003\">'+s+'</div>'+\r\n    '<p class=\"hint\">iPhone 相机对准二维码 → 点链接 → 自动弹出「订阅日历」。</p>';\r\n}\r\n\r\n/* ---------- 加载 ---------- */\r\nasync function load(){\r\n  const key = sessionStorage.getItem('ics_edit_key') || '';\r\n  const r = await fetch('/api/config',{cache:'no-store', headers: key ? {'X-Editor-Key': key} : {}});\r\n  if (!r.ok) {\r\n    const err = await r.json().catch(()=>({}));\r\n    toast('加载配置失败:'+(err.error||r.status), true);\r\n    cfg = { site_base_url:'', defaults:{timezone:'Asia/Shanghai',years_ahead:2}, calendars:[] };\r\n  } else {\r\n    const j = await r.json();\r\n    cfg = j.config;\r\n  }\r\n  metaTime = new Date().toLocaleString('zh-CN');\r\n  $('meta').textContent = '· 配置加载于 ' + metaTime;\r\n  render();\r\n}\r\n\r\n/* ---------- 渲染 ---------- */\r\nfunction summarize(s){\r\n  const parts=[];\r\n  if (s.type==='lunar'){\r\n    parts.push(`农历${CN_MONTH[s.lunar_month-1]}月${s.lunar_day}日`, s.kind==='birthday'?'生日':'纪念日');\r\n    if (s.birth_year) parts.push(`出生${s.birth_year}`);\r\n  } else if (s.type==='solar'){ parts.push(`每年 ${String(s.month).padStart(2,'0')}-${String(s.day).padStart(2,'0')}`); }\r\n  else if (s.type==='rule'){\r\n    const f={weekly:'每周',monthly:'每月',yearly:'每年',once:'单次'}[s.freq]||s.freq;\r\n    let d='';\r\n    if (s.freq==='weekly') d=(WEEKDAYS.find(w=>w[0]===s.weekday)||['',''])[1];\r\n    if (s.freq==='monthly') d=`${s.day} 号`;\r\n    if (s.freq==='yearly') d=`${s.month} 月 ${s.day} 日`;\r\n    if (s.freq==='once') d=s.date||'';\r\n    parts.push((`${f} · ${d}`).replace(/ · $/,''));\r\n    if (s.end) parts.push('至 '+s.end);\r\n  } else if (s.type==='solar-term'){\r\n    let p=s.term;\r\n    if (s.offset_days) p+=` ${s.offset_days>0?'+':''}${s.offset_days}天`;\r\n    if ((s.days??1)>1) p+=` 起·连续${s.days}天`;\r\n    parts.push(p);\r\n  } else if (s.type==='lunar-festival'){\r\n    parts.push(s.festival||'(未选节日)');\r\n  } else if (s.type==='holidays-cn'){\r\n    parts.push([s.include_rest_days!==false&&'放假', s.include_workdays&&'补班'].filter(Boolean).join('+')||'未选择');\r\n  } else if (s.type==='solar-terms'){\r\n    parts.push('二十四节气 · 全部24个');\r\n  }\r\n  if (s.time) parts.push(s.time);\r\n  const al=[...(s.alarm_days_before??[]).map(n=>`提前${n}天`), ...(s.alarms??[])];\r\n  if (al.length) parts.push('提醒:'+al.join(','));\r\n  if (s.note) parts.push(s.note);\r\n  return parts.join(' · ');\r\n}\r\n\r\nfunction renderTabs(){\r\n  const el=$('tabs');\r\n  el.innerHTML = cfg.calendars.map((c,i)=>\r\n    `<span class=\"tab ${i===active?'active':''}\" data-i=\"${i}\">${esc(c.name)}</span>`).join('')\r\n    + `<span class=\"tab\" id=\"addCalBtn\">＋ 新建日历</span>`;\r\n  el.querySelectorAll('.tab[data-i]').forEach(n=>n.onclick=()=>{active=Number(n.dataset.i);render();});\r\n  $('addCalBtn').onclick=openNewCalendar;\r\n}\r\n\r\nfunction renderCal(){\r\n  const c=cfg.calendars[active];\r\n  const panel=$('calPanel');\r\n  const priv=c.access==='private';\r\n  panel.innerHTML=`\r\n    <div class=\"cardbox\"><div class=\"row\">\r\n      <label class=\"f\" style=\"flex:2;min-width:170px\"><span><b>日历名称</b>(iPhone 显示)</span>\r\n        <input id=\"calName\" value=\"${esc(c.name)}\"></label>\r\n      <label class=\"f\" style=\"flex:3;min-width:200px\"><span>描述(可选)</span>\r\n        <input id=\"calDesc\" value=\"${esc(c.description??'')}\"></label>\r\n      <button class=\"btn danger small\" id=\"delCalBtn\">删除日历</button>\r\n    </div>\r\n    <div class=\"row\" style=\"margin-top:10px\">\r\n      <div class=\"f\"><span><b>订阅方式</b></span>\r\n        <div class=\"seg\" id=\"accSeg\">\r\n          <button type=\"button\" class=\"segbtn ${priv?'':'on'}\" data-acc=\"public\">🌐 公开</button>\r\n          <button type=\"button\" class=\"segbtn ${priv?'on':''}\" data-acc=\"private\">🔒 私密</button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div id=\"accNote\"></div>\r\n    </div>\r\n    <div class=\"cardbox\">\r\n      ${c.sources.map((s,i)=>`\r\n      <div class=\"ev\">\r\n        <span class=\"ico\">${TYPES[s.type]?.icon||'❓'}</span>\r\n        <div class=\"info\">\r\n          <div class=\"t\">${esc(s.title||TYPES[s.type]?.label||s.type)}</div>\r\n          <div class=\"s\">${esc(summarize(s))}</div>\r\n        </div>\r\n        <div class=\"ops\">\r\n          <button class=\"btn ghost small\" data-up=\"${i}\" ${i===0?'disabled':''}>↑</button>\r\n          <button class=\"btn ghost small\" data-down=\"${i}\" ${i===c.sources.length-1?'disabled':''}>↓</button>\r\n          <button class=\"btn secondary small\" data-edit=\"${i}\">✎</button>\r\n          <button class=\"btn danger small\" data-del=\"${i}\">🗑</button>\r\n        </div>\r\n      </div>`).join('') || '<p class=\"hint\">还没有事件,点下面按钮添加。</p>'}\r\n      <div style=\"margin-top:12px\"><button class=\"btn\" id=\"addEvBtn\">＋ 添加事件</button></div>\r\n    </div>`;\r\n  $('calName').onchange=e=>{cfg.calendars[active].name=e.target.value.trim()||c.name;renderTabs();};\r\n  $('calDesc').onchange=e=>{const d=e.target.value.trim();if(d)cfg.calendars[active].description=d;else delete cfg.calendars[active].description;};\r\n  $('delCalBtn').onclick=()=>{ if(!confirm(`确定删除「${c.name}」及其 ${c.sources.length} 个事件?`))return;\r\n    cfg.calendars.splice(active,1); active=Math.max(0,active-1); render(); };\r\n  $('addEvBtn').onclick=()=>openEventForm(active,-1);\r\n  panel.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEventForm(active,Number(b.dataset.edit)));\r\n  panel.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{ if(!confirm('删除这条事件?'))return;\r\n    cfg.calendars[active].sources.splice(Number(b.dataset.del),1); render(); });\r\n  panel.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>moveSrc(Number(b.dataset.up),-1));\r\n  panel.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>moveSrc(Number(b.dataset.down),1));\r\n  // 订阅方式开关\r\n  $('accSeg').querySelectorAll('.segbtn').forEach(b=>b.onclick=async()=>{\r\n    const acc=b.dataset.acc;\r\n    if(acc===cfg.calendars[active].access) return;\r\n    cfg.calendars[active].access=acc;\r\n    renderCal();\r\n    if(acc==='private') await fillPrivateLink();\r\n    toast(acc==='private'?'🔒 已设为私密:保存后首页将隐藏该日历链接':'🌐 已设为公开');\r\n  });\r\n  if(priv) fillPrivateLink();\r\n}\r\nasync function fillPrivateLink(){\r\n  const c=cfg.calendars[active]; const note=$('accNote'); if(!note) return;\r\n  const tok=await subTokenFor(c.id);\r\n  if(!tok){\r\n    note.innerHTML='<p class=\"hint\">⚠️ 当前会话没有密钥材料(未启用访问密钥或刚清空会话)。重新解锁一次即可生成私密链接。</p>'; return;\r\n  }\r\n  const url=`${siteBase()}/s/${tok}/${c.id}.ics`;\r\n  note.innerHTML=`<p class=\"hint\" style=\"margin-top:8px\">私密订阅专属链接(发给家人即订;iPhone 里粘贴到「添加订阅日历」,或扫码):</p>\r\n    <div class=\"row\" style=\"gap:8px\">\r\n      <input readonly value=\"${esc(url)}\" style=\"flex:1;font-size:12px;padding:7px;border-radius:8px;border:1px solid #8886;color:inherit;background:transparent\">\r\n      <button class=\"btn small\" id=\"copySub\">📋 复制</button>\r\n    </div>\r\n    <div style=\"margin-top:10px\" id=\"privQr\"></div>\r\n    <p class=\"hint\">令牌按日历独立派生,泄露此链接不影响其他日历;轮换访问密钥会使所有私密链接失效(重新复制新链即可)。⚠️ 二维码含专属令牌,请只私下发给家人朋友。</p>`;\r\n  $('copySub').onclick=()=>{ navigator.clipboard.writeText(url).then(()=>toast('已复制'),()=>toast('复制失败,请手动选择',true)); };\r\n  renderQrInto($('privQr'), webcalOf(url));\r\n}\r\nfunction moveSrc(i,d){ const a=cfg.calendars[active].sources; [a[i],a[i+d]]=[a[i+d],a[i]]; render(); }\r\nfunction render(){ if(!cfg)return; renderTabs(); renderCal(); }\r\n\r\n/* ---------- 表单 ---------- */\r\nfunction fld(label,inner){return `<label class=\"f\"><span><b>${label}</b></span>${inner}</label>`;}\r\nfunction commonFields(s){\r\n  return `<div class=\"grid\">\r\n    ${fld('标题(必填)',`<input id=\"f_title\" value=\"${esc(s.title??'')}\" placeholder=\"如:妈妈生日\">`)}\r\n    ${fld('提醒时间(留空=全天)',`<input id=\"f_time\" type=\"time\" value=\"${esc(s.time??'')}\">`)}</div>\r\n    <h2 class=\"sect\">提醒方式</h2>\r\n    <div class=\"grid\">\r\n    <div class=\"f\"><span><b>提前几天全天提醒</b></span>\r\n      <div class=\"chips\" id=\"f_adb\">${ALARM_DAYS.map(d=>\r\n        `<span class=\"chip ${(s.alarm_days_before??[]).includes(d)?'on':''}\" data-d=\"${d}\">${d===0?'当天':'前 '+d+' 天'}</span>`).join('')}</div></div>\r\n    ${fld('自定义提醒(逗号分隔)',`<input id=\"f_alarms\" value=\"${esc((s.alarms??[]).join(','))}\" placeholder=\"-P1D,-PT9H\">`)}</div>\r\n    ${fld('备注(可选)',`<input id=\"f_note\" value=\"${esc(s.note??'')}\">`)}`;\r\n}\r\nfunction readCommon(s){\r\n  s.title=$('f_title').value.trim();\r\n  const t=$('f_time').value; if(t)s.time=t; else delete s.time;\r\n  const adb=[...document.querySelectorAll('#f_adb .chip.on')].map(n=>Number(n.dataset.d)).sort((a,b)=>a-b);\r\n  if(adb.length)s.alarm_days_before=adb; else delete s.alarm_days_before;\r\n  const al=$('f_alarms').value.split(',').map(x=>x.trim()).filter(Boolean);\r\n  if(al.length)s.alarms=al; else delete s.alarms;\r\n  const note=$('f_note').value.trim(); if(note)s.note=note; else delete s.note;\r\n}\r\nconst FORMS={\r\n  'lunar'(s){return `<div class=\"grid\">\r\n    ${fld('农历月份',`<select id=\"f_lm\">${CN_MONTH.map((m,i)=>`<option value=\"${i+1}\" ${s.lunar_month===i+1?'selected':''}>${m}月</option>`).join('')}</select>`)}\r\n    ${fld('农历日期(初一=1)',`<input id=\"f_ld\" type=\"number\" min=\"1\" max=\"30\" value=\"${s.lunar_day??1}\">`)}\r\n    ${fld('类型',`<select id=\"f_kind\"><option value=\"birthday\" ${s.kind!=='memorial'?'selected':''}>🎂 生日</option><option value=\"memorial\" ${s.kind==='memorial'?'selected':''}>🕯️ 纪念日</option></select>`)}\r\n    ${fld('出生年份(公历,可选→虚岁)',`<input id=\"f_by\" type=\"number\" min=\"1900\" max=\"2100\" value=\"${s.birth_year??''}\">`)}</div>`;},\r\n  'read-lunar'(s){s.lunar_month=Number($('f_lm').value);s.lunar_day=Number($('f_ld').value);s.kind=$('f_kind').value;\r\n    const by=$('f_by').value?Number($('f_by').value):undefined;if(by)s.birth_year=by;else delete s.birth_year;},\r\n  'solar'(s){return `<div class=\"grid\">\r\n    ${fld('月份',`<select id=\"f_m\">${Array.from({length:12},(_,i)=>`<option value=\"${i+1}\" ${s.month===i+1?'selected':''}>${i+1} 月</option>`).join('')}</select>`)}\r\n    ${fld('日期',`<input id=\"f_d\" type=\"number\" min=\"1\" max=\"31\" value=\"${s.day??1}\">`)}</div>`;},\r\n  'read-solar'(s){s.month=Number($('f_m').value);s.day=Number($('f_d').value);},\r\n  'rule'(s){return `<div class=\"grid\">${fld('重复频率',`<select id=\"f_freq\">${['monthly','weekly','yearly','once'].map(f=>`<option value=\"${f}\" ${(s.freq??'monthly')===f?'selected':''}>${({weekly:'每周',monthly:'每月',yearly:'每年',once:'单次'})[f]}</option>`).join('')}</select>`)}</div>\r\n    <div class=\"cond grid\" id=\"ruleCond\"></div>`;},\r\n  'read-rule'(s){s.freq=$('f_freq').value;const g=id=>$(id)?.value;\r\n    delete s.weekday;delete s.day;delete s.month;delete s.date;\r\n    if(s.freq==='weekly')s.weekday=g('f_wd');\r\n    if(s.freq==='monthly')s.day=Number(g('f_md'));\r\n    if(s.freq==='yearly'){s.month=Number(g('f_ym'));s.day=Number(g('f_yd'));}\r\n    if(s.freq==='once'&&g('f_od'))s.date=g('f_od');\r\n    const st=g('f_start'),en=g('f_end');\r\n    if(st)s.start=st;else delete s.start;\r\n    if(en)s.end=en;else delete s.end;},\r\n  'solar-term'(s){return `<div class=\"grid\">\r\n    ${fld('节气',`<select id=\"f_term\">${TERMS.map(t=>`<option ${s.term===t?'selected':''}>${t}</option>`).join('')}</select>`)}\r\n    ${fld('偏移天数(前一天=-1,最多±183)',`<input id=\"f_off\" type=\"number\" min=\"-183\" max=\"183\" value=\"${s.offset_days??0}\">`)}\r\n    ${fld('连续展开天数(1~366)',`<input id=\"f_days\" type=\"number\" min=\"1\" max=\"366\" value=\"${s.days??1}\">`)}</div>`;},\r\n  'read-solar-term'(s){\r\n    s.term=$('f_term').value;\r\n    const off=Number($('f_off').value); s.offset_days=Math.max(-183,Math.min(183,Number.isFinite(off)?Math.trunc(off):0));\r\n    const d=Number($('f_days').value); s.days=Math.max(1,Math.min(366,Number.isFinite(d)?Math.trunc(d):1));\r\n  },\r\n  'lunar-festival'(s){return `<div class=\"grid\">\r\n    ${fld('节日',`<select id=\"f_lf\" onchange=\"document.getElementById('f_title').value=this.value\">${LUNAR_FESTIVALS.map(t=>`<option ${s.festival===t?'selected':''}>${t}</option>`).join('')}</select>`)}\r\n    </div>\r\n    <p class=\"hint\">标题已自动取为节日名(可在上方修改);除夕自动落在腊月最后一天。</p>`;},\r\n  'read-lunar-festival'(s){\r\n    s.festival=$('f_lf').value;\r\n    if(!s.title) s.title=s.festival; // 未手动填则用节日名\r\n  },\r\n  'holidays-cn'(s){return `<div class=\"hint\" style=\"margin-bottom:10px\">每日历最多一个数据源,勾选要生成的类别:</div>\r\n    <div class=\"chips\"><span class=\"chip ${s.include_rest_days!==false?'on':''}\" id=\"f_rest\">🎉 放假日</span>\r\n    <span class=\"chip ${!!s.include_workdays?'on':''}\" id=\"f_work\">💼 调休补班(Apple 缺失)</span></div>`;},\r\n  'read-holidays-cn'(s){s.include_rest_days=$('f_rest').classList.contains('on');\r\n    s.include_workdays=$('f_work').classList.contains('on');\r\n    delete s.title;delete s.time;delete s.note;delete s.alarms;delete s.alarm_days_before;},\r\n  'solar-terms'(s){return `<p class='hint'>一次性展开全部二十四节气(立春~大寒),标题自动取节气名;无需逐个配置。下方公共字段(时间/提醒/备注)对所有节气生效。</p>`;},\r\n  'read-solar-terms'(s){ delete s.title; },\r\n};\r\nfunction renderRuleCond(){\r\n  const box=$('ruleCond'); if(!box)return;\r\n  const fq=$('f_freq').value, s=editSnapshot; let html='';\r\n  if(fq==='weekly') html+=fld('星期几',`<select id=\"f_wd\">${WEEKDAYS.map(w=>`<option value=\"${w[0]}\" ${s.weekday===w[0]?'selected':''}>${w[1]}</option>`).join('')}</select>`);\r\n  if(fq==='monthly') html+=fld('每月几号',`<input id=\"f_md\" type=\"number\" min=\"1\" max=\"31\" value=\"${s.day??1}\">`);\r\n  if(fq==='yearly') html+=fld('月份',`<select id=\"f_ym\">${Array.from({length:12},(_,i)=>`<option value=\"${i+1}\" ${s.month===i+1?'selected':''}>${i+1} 月</option>`).join('')}</select>`)\r\n    +fld('日期',`<input id=\"f_yd\" type=\"number\" min=\"1\" max=\"31\" value=\"${s.day??1}\">`);\r\n  if(fq==='once') html+=fld('具体日期',`<input id=\"f_od\" type=\"date\" value=\"${esc(s.date??'')}\">`);\r\n  html+=fld('开始日期(可选)',`<input id=\"f_start\" type=\"date\" value=\"${esc(s.start??'')}\">`)\r\n    +fld('结束日期(可选)',`<input id=\"f_end\" type=\"date\" value=\"${esc(s.end??'')}\">`);\r\n  box.innerHTML=html;\r\n}\r\nfunction openEventForm(ci,si){\r\n  const isNew=si===-1, existing=isNew?null:cfg.calendars[ci].sources[si];\r\n  editSnapshot=structuredClone(existing??{}); editState={ci,si};\r\n  $('dlgTitle').textContent=isNew?'添加事件':'编辑事件';\r\n  $('dlgBody').innerHTML=`\r\n    ${isNew?`<div class=\"typegrid\">${Object.entries(TYPES).map(([t,m])=>\r\n      `<div class=\"typeopt ${t==='lunar'?'on':''}\" data-t=\"${t}\"><span class=\"i\">${m.icon}</span>${m.label}</div>`).join('')}</div>`\r\n      :`<p class=\"hint\">类型:${TYPES[existing.type].icon} ${TYPES[existing.type].label}(改类型请删除重加)</p>`}\r\n    <div class=\"grid\" style=\"margin-bottom:14px\">${commonFields(editSnapshot)}</div>\r\n    <div id=\"typedFields\"></div>`;\r\n  function bindCommon(){\r\n    $('f_title').onchange=e=>editSnapshot.title=e.target.value.trim();\r\n    $('f_time').onchange=e=>{if(e.target.value)editSnapshot.time=e.target.value;else delete editSnapshot.time;};\r\n    document.querySelectorAll('#f_adb .chip').forEach(ch=>ch.onclick=()=>ch.classList.toggle('on'));\r\n    $('f_alarms').onchange=e=>{const al=e.target.value.split(',').map(x=>x.trim()).filter(Boolean);\r\n      if(al.length)editSnapshot.alarms=al;else delete editSnapshot.alarms;};\r\n    $('f_note').onchange=e=>{if(e.target.value.trim())editSnapshot.note=e.target.value.trim();else delete editSnapshot.note;};\r\n  }\r\n  function renderTyped(t){\r\n    editSnapshot.type=t;\r\n    $('typedFields').innerHTML=FORMS[t]?FORMS[t](editSnapshot):'';\r\n    if(t==='rule'){$('f_freq').onchange=renderRuleCond;renderRuleCond();}\r\n    bindCommon();\r\n  }\r\n  if(isNew) $('dlg').querySelectorAll('.typeopt').forEach(op=>op.onclick=()=>{\r\n    $('dlg').querySelectorAll('.typeopt').forEach(o=>o.classList.remove('on'));\r\n    op.classList.add('on'); renderTyped(op.dataset.t);\r\n  });\r\n  renderTyped(existing?.type??'lunar');\r\n  $('dlg').showModal();\r\n}\r\nfunction closeDlg(){ $('dlgOk').onclick=submitDlg; $('dlg').close(); }\r\nfunction submitDlg(){\r\n  const {ci,si}=editState; const s=structuredClone(editSnapshot);\r\n  readCommon(s); FORMS['read-'+s.type]?.(s);\r\n  if(!s.title){toast('标题不能为空',true);return;}\r\n  if(si===-1)cfg.calendars[ci].sources.push(s); else cfg.calendars[ci].sources[si]=s;\r\n  closeDlg(); render(); toast('已加入列表,记得「保存到云端」才会生效');\r\n}\r\nfunction openNewCalendar(){\r\n  $('dlgTitle').textContent='新建日历';\r\n  $('dlgBody').innerHTML=`<div class=\"grid\">\r\n    ${fld('日历 ID(小写英文,创建后不可改)',`<input id=\"nc_id\" placeholder=\"my-calendar\">`)}\r\n    ${fld('日历名称',`<input id=\"nc_name\" placeholder=\"🎂 我的日历\">`)}</div>`;\r\n  $('dlg').showModal();\r\n  $('dlgOk').onclick=()=>{\r\n    const id=$('nc_id').value.trim(),name=$('nc_name').value.trim();\r\n    if(!/^[a-z0-9][a-z0-9-]{0,62}$/.test(id)){toast('ID 只能是小写字母数字连字符',true);return;}\r\n    if(!name){toast('名称不能为空',true);return;}\r\n    if(cfg.calendars.some(c=>c.id===id)){toast('ID 已存在',true);return;}\r\n    cfg.calendars.push({id,name,sources:[]});\r\n    active=cfg.calendars.length-1; closeDlg(); render();\r\n  };\r\n}\r\nfunction openSettings(){\r\n  $('dlgTitle').textContent='全局设置';\r\n  $('dlgBody').innerHTML=`<div class=\"grid\">\r\n    ${fld('时区',`<select id=\"st_tz\">${['Asia/Shanghai','Asia/Hong_Kong','Asia/Taipei','Asia/Singapore','UTC'].map(z=>`<option ${cfg.defaults.timezone===z?'selected':''}>${z}</option>`).join('')}</select>`)}\r\n    ${fld('向未来展开几年',`<input id=\"st_ya\" type=\"number\" min=\"1\" max=\"10\" value=\"${cfg.defaults.years_ahead}\">`)}</div>\r\n    <p class=\"hint\">站点地址与访问密钥已迁移到仓库的 Actions Variables / Secrets(CAL_SITE_BASE_URL、CAL_EDITOR_KEY),不在此处管理。</p>`;\r\n  $('dlg').showModal();\r\n  $('dlgOk').onclick=()=>{\r\n    cfg.defaults.timezone=$('st_tz').value;\r\n    cfg.defaults.years_ahead=Number($('st_ya').value)||2;\r\n    closeDlg(); toast('设置已记录,保存到云端后生效');\r\n  };\r\n}\r\nfunction openKeySettings(){\r\n  const cur = sessionStorage.getItem('ics_edit_key') || '';\r\n  $('dlgTitle').textContent='🔑 访问密钥';\r\n  $('dlgBody').innerHTML=`\r\n    ${fld('UUID 密钥(用于读写配置 API + 派生私密订阅链接)',`<input id=\"key_input\" type=\"password\" value=\"${esc(cur)}\" autocomplete=\"off\" placeholder=\"xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx\">`)}\r\n    <p class=\"hint\" style=\"margin-top:10px\">密钥只保存在当前浏览器会话(sessionStorage),关闭标签页后清除。<br>\r\n    用于:① 调用 /api/config 读写私人日历配置;② 在浏览器端派生私密日历的订阅令牌。<br>\r\n    服务端只存密钥的 SHA-256 哈希,不存原始 UUID。</p>`;\r\n  $('dlg').showModal();\r\n  $('dlgOk').onclick=()=>{\r\n    const v = $('key_input').value.trim().toLowerCase();\r\n    if (v) {\r\n      sessionStorage.setItem('ics_edit_key', v);\r\n      toast('密钥已更新,重新加载配置…');\r\n      closeDlg();\r\n      load();\r\n    } else {\r\n      toast('密钥不能为空', true);\r\n    }\r\n  };\r\n}\r\nfunction logLine(s){ const l=$('log'); l.style.display='block'; l.textContent+=s+'\\n'; l.scrollTop=l.scrollHeight; }\r\n\r\n/* ---------- 保存到云端(Worker KV) ---------- */\r\n\r\n/* 提交前的轻量校验:镜像服务端 zod 的关键约束,把问题拦在浏览器里而不是 CI */\r\nfunction validateCfg(){\r\n  const errs=[];\r\n  const int=(v,min,max)=>typeof v==='number'&&Number.isInteger(v)&&v>=min&&v<=max;\r\n  cfg.calendars.forEach((c,ci)=>{\r\n    const at=(j)=>`日历${ci+1}「${c.name||c.id}」第 ${j+1} 项`;\r\n    if(!/^[a-z0-9][a-z0-9-]{0,62}$/.test(c.id)) errs.push(`日历 ID 非法:${c.id}`);\r\n    if(!c.name) errs.push(`日历「${c.id}」缺名称`);\r\n    c.sources.forEach((s,j)=>{\r\n      if(s.type!=='holidays-cn' && s.type!=='solar-terms' && !(s.title??'').trim()) errs.push(`${at(j)} 缺标题`);\r\n      if(s.time && !/^([01]\\d|2[0-3]):[0-5]\\d$/.test(s.time)) errs.push(`${at(j)} 时间须为 HH:mm`);\r\n      switch(s.type){\r\n        case 'lunar':\r\n          if(!int(s.lunar_month,1,12)) errs.push(`${at(j)} 农历月须为 1~12`);\r\n          if(!int(s.lunar_day,1,30))   errs.push(`${at(j)} 农历日须为 1~30`);\r\n          break;\r\n        case 'solar':\r\n          if(!int(s.month,1,12)) errs.push(`${at(j)} 月份须为 1~12`);\r\n          if(!int(s.day,1,31))   errs.push(`${at(j)} 日期须为 1~31`);\r\n          break;\r\n        case 'rule':\r\n          if(!['weekly','monthly','yearly','once'].includes(s.freq)) errs.push(`${at(j)} 频率非法`);\r\n          if(s.freq==='weekly' && !s.weekday) errs.push(`${at(j)} weekly 需选星期几`);\r\n          if(s.freq==='monthly' && !int(s.day,1,31)) errs.push(`${at(j)} monthly 需填日期(1~31)`);\r\n          if(s.freq==='yearly' && (!int(s.month,1,12)||!int(s.day,1,31))) errs.push(`${at(j)} yearly 需填月和日`);\r\n          if(s.freq==='once' && !/^\\d{4}-\\d{2}-\\d{2}$/.test(s.date??'')) errs.push(`${at(j)} once 需填具体日期`);\r\n          break;\r\n        case 'solar-term':\r\n          if(!TERMS.includes(s.term)) errs.push(`${at(j)} 节气名非法`);\r\n          if(!int(s.offset_days,-183,183)) errs.push(`${at(j)} 偏移天数须为 -183~183 的整数`);\r\n          if(!int(s.days,1,366)) errs.push(`${at(j)} 连续天数须为 1~366 的整数(当前 ${JSON.stringify(s.days)})`);\r\n          break;\r\n        case 'lunar-festival':\r\n          if(!LUNAR_FESTIVALS.includes(s.festival)) errs.push(`${at(j)} 节日名非法`);\r\n          break;\r\n      }\r\n    });\r\n  });\r\n  return errs;\r\n}\r\n\r\nasync function saveToWorker(){\r\n  const nameEl=$('calName'),descEl=$('calDesc');\r\n  if(nameEl&&cfg.calendars[active])cfg.calendars[active].name=nameEl.value.trim()||cfg.calendars[active].name;\r\n  if(descEl&&cfg.calendars[active]){const d=descEl.value.trim();if(d)cfg.calendars[active].description=d;else delete cfg.calendars[active].description;}\r\n\r\n  // 先校验\r\n  const errs=validateCfg();\r\n  if(errs.length){\r\n    logLine(`[${now()}] ❌ 配置有 ${errs.length} 处问题,未保存:`);\r\n    errs.slice(0,8).forEach(e=>logLine('       · '+e));\r\n    toast(errs[0],true); return;\r\n  }\r\n\r\n  const key = sessionStorage.getItem('ics_edit_key');\r\n  if(!key){ openKeySettings(); toast('需要访问密钥才能保存',true); return; }\r\n\r\n  // 只发送私人日历(公开日历 cn-holidays 内置在 Worker 代码中,不可编辑)\r\n  const privateCals = cfg.calendars.filter(c => c.id !== 'cn-holidays');\r\n\r\n  const btn=$('saveBtn'); btn.disabled=true; btn.textContent='⏳ 保存中…';\r\n  try{\r\n    logLine(`[${now()}] 保存 ${privateCals.length} 个私人日历到 KV…`);\r\n    const res = await fetch('/api/config',{\r\n      method:'POST',\r\n      headers:{ 'Content-Type':'application/json', 'X-Editor-Key': key },\r\n      body: JSON.stringify(privateCals),\r\n    });\r\n    const j = await res.json().catch(()=>({}));\r\n    if(!res.ok){ throw new Error(`保存失败 HTTP ${res.status}:${j.error||''}${j.issues?' · '+j.issues.map(i=>i.path+':'+i.message).join('; '):''}`); }\r\n    logLine(`[${now()}] ✅ 已保存 ${j.saved} 个私人日历到 KV,立即生效`);\r\n    toast('✅ 已保存,立即生效');\r\n  }catch(e){\r\n    logLine(`[${now()}] ❌ ${e.message}`);\r\n    toast('保存失败:'+e.message,true);\r\n  }finally{\r\n    btn.disabled=false; btn.textContent='💾 保存到云端';\r\n  }\r\n}\r\nfunction now(){ return new Date().toLocaleTimeString('zh-CN',{hour12:false}); }\r\n\r\n/* ---------- 启动 ---------- */\r\n(async function init(){\r\n  await gate();\r\n  await load();\r\n})();\r\n</script>\r\n</body>\r\n</html>\r\n";

export const YAML_DUMP_JS: string = "// 自动生成于构建期:与 Node 端完全一致的 YAML 序列化器(勿手改)\nconst __name = (fn) => fn; // 兼容 tsx/esbuild keepNames 注入的名称保留辅助\nfunction dumpYaml(value,indent=0){const pad=\"  \".repeat(indent);const scalar=__name(v=>{if(v===null||v===void 0)return\"null\";if(typeof v===\"number\")return Number.isFinite(v)?String(v):\"null\";if(typeof v===\"boolean\")return v?\"true\":\"false\";if(typeof v===\"string\"){const s=v.replace(/\\\\/g,\"\\\\\\\\\").replace(/\"/g,'\\\\\"').replace(/\\r/g,\"\\\\r\").replace(/\\n/g,\"\\\\n\").replace(/\\t/g,\"\\\\t\");return`\"${s}\"`}return null},\"scalar\");const isEmptyContainer=__name(v=>Array.isArray(v)?v.length===0:typeof v===\"object\"&&v!==null&&Object.keys(v).length===0,\"isEmptyContainer\");if(Array.isArray(value)){if(value.length===0)return`${pad}[]`;return value.map(item=>{const sc=scalar(item);if(sc!==null)return`${pad}- ${sc}`;const inner=dumpYaml(item,indent+1);const lines=inner.split(\"\\n\");return`${pad}- ${lines[0].trimStart()}${lines.length>1?\"\\n\"+lines.slice(1).join(\"\\n\"):\"\"}`}).join(\"\\n\")}if(typeof value===\"object\"&&value!==null){const entries=Object.entries(value).filter(([,v])=>v!==void 0&&v!==null);if(entries.length===0)return`${pad}{}`;return entries.map(([k,v])=>{const sc=scalar(v);if(sc!==null)return`${pad}${k}: ${sc}`;if(isEmptyContainer(v))return`${pad}${k}: ${Array.isArray(v)?\"[]\":\"{}\"}`;return`${pad}${k}:\n${dumpYaml(v,indent+1)}`}).join(\"\\n\")}return String(value)}\n";

export interface StaticAsset {
  route: string;
  contentType: string;
  content: string;
}

export const STATIC_ASSETS: StaticAsset[] = [
  { route: "/qrcode.min.js", contentType: "application/javascript; charset=utf-8", content: QRCODE_JS },
  { route: "/editor/", contentType: "text/html; charset=utf-8", content: EDITOR_HTML },
  { route: "/editor/index.html", contentType: "text/html; charset=utf-8", content: EDITOR_HTML },
  { route: "/editor/yaml-dump.js", contentType: "application/javascript; charset=utf-8", content: YAML_DUMP_JS },
];
